use crate::tox::friend::Friend;
use crate::types::*;

// The `Group` struct, its `Debug`/`From` impls and the delegating state/peer
// methods are generated by apigen; pull them in as the wrapper module's
// primary definition.
#[path = "../core/generated/safe_group.rs"]
mod generated;
pub use generated::Group;

// The methods below cannot be derived from the model: `invite_friend` takes a
// `&Friend` where the C function takes a bare `Tox_Friend_Number`, and `leave`
// / `set_password` expose an optional buffer (`None` -> empty slice).
impl<'a> Group<'a> {
    pub fn invite_friend(&self, friend: &Friend) -> Result<()> {
        self.tox
            .inner
            .core
            .group_invite_friend(self.number, friend.get_number())
            .map_err(ToxError::GroupInviteFriend)
    }

    pub fn leave(self, part_message: Option<&[u8]>) -> Result<()> {
        self.tox
            .inner
            .core
            .group_leave(self.number, part_message.unwrap_or(&[]))
            .map_err(ToxError::GroupLeave)
    }

    pub fn set_password(&self, password: Option<&[u8]>) -> Result<()> {
        self.tox
            .inner
            .core
            .group_set_password(self.number, password.unwrap_or(&[]))
            .map_err(ToxError::GroupSetPassword)
    }
}
